#Funcion Generador Congruencial
def GeneradorCongruencialCastilloEnterprises(listaprimos, numeros=10000):
    a = listaprimos[0]
    C = listaprimos[1]
    x0 = listaprimos[2]
    M = 2147483647 #Soy un numero de Don Mersenne
    Ri = []
    for i in range(numeros):
        xi = a * x0 + C
        xi = xi % M
        x0 = xi
        r = xi/M
        Ri.append(r)
        if Ri[0] == r and len(Ri) > 2:
            del Ri[-1]
            break
    return Ri
