def GeneradorCongruencialMixto(a, c, semilla, m, numeros=10000):
    """La función "GeneradorCongruencialMixto" en Python toma cinco argumentos:
    "a", "c", "semilla", "m" y "numeros". "a" y "c" son constantes utilizadas en el cálculo
    de los números aleatorios, "m" es el Módulo a utilizar y validador de congruencialidad y "semilla" es el valor inicial utilizado en el cálculo y
    "numeros" es la cantidad de números aleatorios que se generarán.
    La función utiliza un generador congruencial mixto para generar una lista de números aleatorios.
    La función utiliza una fórmula matemática que depende de los valores de "a", "c", "semilla"
    y "numeros" para calcular los números aleatorios.
    La función devuelve una lista de los números aleatorios generados.
    La función también tiene un docstring que proporciona una descripción de la función,
    los argumentos que toma y lo que devuelve.

    Args:
        a (int): constante multiplicativa
        c (int): constante aditiva
        m (int): Módulo de congruencialidad
        semilla (int): semilla independiente
        numeros (int, optional): Cantidad de numeros a generar, por defecto se generan 10mil
    Returns:
        list: Lista con 10mil numeros aleatorios
    """
    a = int(a)
    c = int(c)
    x = []
    r = []
    m = int(m)
    semilla = int(semilla)
    x.append(semilla) # Semilla queda en la posicion X0
    for i in range(1, numeros + 1):
        n = (a*x[i-1]+c)
        n = n % m
        x.append(n)
        r.append(n/m)
    return r #No se tienen las validaciones relacionadas. Recuerde hacerlas
