def Exponencial(vlLambda):
    """
    Calcula un valor aleatorio de una distribución exponencial usando el método de la inversa de la función acumulativa.

    Parameters:
    vlLambda (float): El parámetro lambda de la distribución exponencial (tasa de ocurrencia).

    Returns:
    float: Un valor aleatorio que sigue una distribución exponencial con el parámetro proporcionado.
    """
    exponencial = -log(1-rnd.random())/vlLambda
    return exponencial

def Uniforme(a, b):
    """
    Genera un valor aleatorio de una distribución uniforme en el intervalo [a, b].

    Parameters:
    a (float): El límite inferior del intervalo.
    b (float): El límite superior del intervalo.
    aleatorio (int, optional): Parámetro opcional, actualmente no utilizado en el cálculo. Valor predeterminado es 0.

    Returns:
    float: Un valor aleatorio dentro del intervalo [a, b] que sigue una distribución uniforme.
    """
    x = a + (b - a)*rnd.random()
    return x

def Triangular(a, b, c):
    """
    Genera un valor aleatorio de una distribución triangular definida por los límites [a, c] y el modo b.

    Parameters:
    a (float): El límite inferior del intervalo.
    b (float): El valor más probable o moda de la distribución (debe cumplir que a <= b <= c).
    c (float): El límite superior del intervalo.

    Returns:
    float: Un valor aleatorio que sigue una distribución triangular con los parámetros dados.
    """
    aleatorio = rnd.random()
    if aleatorio <= ((b-a)/(c-a)):
        a1 = ((c-a)*(b-a))*rnd.random()
        t = a + (a1**(1/2))
    else:
        a2 = ((1-rnd.random())*(c-b)*(c-a))
        t = c - (a2**(1/2))
    return t

def Bernoulli(p=0.5):
    """
    Genera un valor aleatorio siguiendo una distribución de Bernoulli, que retorna 1 con probabilidad p y 0 con probabilidad (1 - p).

    Parameters:
    p (float, optional): La probabilidad de obtener 1. Debe estar en el intervalo [0, 1]. Valor predeterminado es 0.5.

    Returns:
    int: Retorna 1 con probabilidad p, y 0 con probabilidad (1 - p).
    """
    if rnd.random() <= p:
        return 1
    else:
        return 0

def Binomial(p=0.5, n=1):
    """
    Genera un valor aleatorio siguiendo una distribución binomial, que representa el número de éxitos en n ensayos independientes de Bernoulli con probabilidad p.

    Parameters:
    p (float, optional): La probabilidad de éxito en cada ensayo. Debe estar en el intervalo [0, 1]. Valor predeterminado es 0.5.
    n (int, optional): El número de ensayos independientes. Valor predeterminado es 1.

    Returns:
    int: El número de éxitos (1s) en n ensayos de Bernoulli con probabilidad p.
    """
    sum = 0
    for i in range(n):
        sum+=Bernoulli(p)
    return sum

def Poisson(media):
    """
    Genera un valor aleatorio siguiendo una distribución de Poisson, que representa el número de eventos que ocurren en un intervalo de tiempo o espacio dado una tasa promedio (media).

    Parameters:
    media (float): La media de la distribución de Poisson, que representa la tasa promedio de ocurrencia de eventos.

    Returns:
    int: El número de eventos que ocurren en el intervalo dado la tasa promedio especificada.
    """
    y = 0
    x = 0
    bandera = True
    while bandera:
        v = Exponencial(media)
        y = y + v
        if (y > 1):
            bandera = False
        else:
            x = x + 1
    return x

def BMCosenoNormal(mu, sigma):
    """
    Genera un valor aleatorio que sigue una distribución normal (gaussiana) usando el método de Box-Muller con una transformación coseno.

    Parameters:
    mu (float): La media de la distribución normal.
    sigma (float): La desviación estándar de la distribución normal.

    Returns:
    float: Un valor aleatorio que sigue una distribución normal con media mu y desviación estándar sigma.
    """
    normal = mt.sqrt((-2*mt.log(rnd.random())))*mt.cos(2*mt.pi*rnd.random())
    normal = mu+sigma*normal
    return normal

def BMSenoNormal(mu, sigma):
    """
    Genera un valor aleatorio que sigue una distribución normal (gaussiana) usando el método de Box-Muller con una transformación seno.

    Parameters:
    mu (float): La media de la distribución normal.
    sigma (float): La desviación estándar de la distribución normal.

    Returns:
    float: Un valor aleatorio que sigue una distribución normal con media mu y desviación estándar sigma.
    """
    normal = mt.sqrt((-2*mt.log(rnd.random())))*mt.sin(2*mt.pi*rnd.random())
    normal = mu+sigma*normal
    return normal
