import statistics as st
from numpy import random as rnd
import numpy as np
import matplotlib.pyplot as plt
from tqdm import tqdm
def Multiplo100(valor):
    valor = round(valor/100)*100
    return valor

def TipoVenta():
    r = rnd.random()
    if r < 55/100:
        tipo = 'AlimentosBebidas'
        compra = rnd.triangular(3000,5000,25000)
    elif r < (55 + 10)/100:
        tipo = 'AseoLimpieza'
        compra = rnd.randint(1000,17000)
    elif r < (55 + 10 + 15)/100:
        tipo = 'ProductosHogar'
        compra = rnd.triangular(500,1700,12000)
    elif r < (55 + 10 + 15 + 11)/100:
        tipo = 'Mascotas'
        compra = rnd.normal(15000,5000)
        if compra <1:
            compra = 1 #criterio del modelador, es decir esto es un supuesto
    else:
        tipo = 'OtrosServicios'
        compra = rnd.triangular(1000,2500,12000)
    return tipo, Multiplo100(compra)

def CantidadCompradoresDia(dia:str):
    '''
    El argumento dias se interpreta de la siguiente manera:
    args: ['Lunes','Martes','Miercoles','Jueves','Viernes', ' Sabado']
    '''

    #Dias Frios
    if dia == 'Lunes' or dia == 'Miercoles':
        r = rnd.random()
        if r <4/5:
            #estoy en un dia frio normal
            clientes = rnd.randint(50,120)
        else:
            clientes = rnd.normal(200,25)

    elif dia == 'Martes' or dia == 'Jueves':
        r = rnd.random()
        clientes = rnd.triangular(250,300,400)
        if r< 2/5:
            clientes *= 1.25
       # else:
            #pass
    else:
         r = rnd.random()
         clientes = rnd.poisson(500)
         if r < 2/5:
            masclientes = 1 + rnd.uniform(0.22,0.35)
            clientes *= masclientes
            #estamos en un dia caliente
    return int(round(clientes,0))

def Maqui(incremento = True):
    dias = ['Lunes','Martes','Miercoles','Jueves','Viernes', ' Sabado']*4
    dicVentasTipo = {'AlimentosBebidas':[],
                 'AseoLimpieza':[],
                 'ProductosHogar':[],
                 'Mascotas':[],'OtrosServicios':[]
                 }
    for dia in dias:
        clientes = CantidadCompradoresDia(dia)
        if incremento:
           clientes = int(round(clientes*rnd.uniform(1.1,1.2)))
        for cliente in range(clientes):
            tipo,compra = TipoVenta()
            dicVentasTipo[tipo].append(compra)
    return dicVentasTipo


