#------------------------------------------------------------------------------
# Distribuciones
# BatiCinturon

# -------------------------------------------------------------------

import math as mt
import pandas as pd
import random as rnd
import numpy as np
import matplotlib.pyplot as plt
import statistics as st
#from datetime import datetime
from math import log

# -------------------------------------------------------------------

def Exponencial(vlLambda, aleatorio = 0):

    """Calcula un valor de la distribución exponencial con media 'vlLambda'.

    Args:
        vlLambda (int): Media de la distribución exponencial.
        aleatorio (int, optional): Valor para el cálculo. Generado al azar si no se proporciona.

    Returns:
        float: Valor de la distribución exponencial.
    """

    if aleatorio == 0:
        aleatorio = rnd.random()
    exponencial = -log(1-aleatorio)/vlLambda
    return exponencial

# -------------------------------------------------------------------

def Uniforme(a, b, aleatorio = 0):

    """Genera un valor de la distribución uniforme entre 'a' y 'b'.

    Args:
        a (int): Límite inferior.
        b (int): Límite superior.
        aleatorio (int, optional): Valor para el cálculo. Generado al azar si no se proporciona.

    Returns:
        float: Valor de la distribución uniforme.
    """

    if aleatorio == 0:
        aleatorio = rnd.random()
    x = a + (b - a)*aleatorio
    return x

# -------------------------------------------------------------------

def Triangular(a, b, c, aleatorio = 0):

    """Calcula un valor de la distribución triangular con límites 'a', 'b' y 'c'.

    Args:
        a (int): Mínimo.
        b (int): Moda.
        c (int): Máximo.
        aleatorio (int, optional): Valor para el cálculo. Generado al azar si no se proporciona.

    Returns:
        float: Valor de la distribución triangular.
    """

    if aleatorio == 0:
        aleatorio = rnd.random()

    if aleatorio <= ((b-a)/(c-a)):
        a1 = ((c-a)*(b-a))*aleatorio
        t = a + (a1**(1/2))
    else:
        a2 = ((1-aleatorio)*(c-b)*(c-a))
        t = c - (a2**(1/2))

    return t

# -------------------------------------------------------------------

def Bernoulli(p=0.5, aleatorio = 0):

    """Genera un valor de la distribución de Bernoulli con probabilidad 'p'.

    Args:
        p (float, optional): Probabilidad de éxito. Defaults to 0.5.
        aleatorio (int, optional): Valor para el cálculo. Generado al azar si no se proporciona.

    Returns:
        int: 1 o 0 según el resultado de Bernoulli.
    """

    if aleatorio == 0:
        aleatorio = rnd.random()

    if aleatorio <= p:
        return 1
    else:
        return 0

# -------------------------------------------------------------------

def Binomial(p=0.5, n=5):

    """Calcula la distribución binomial con probabilidad 'p' en 'n' intentos.

    Args:
        p (float, optional): Probabilidad de éxito en cada intento. Defaults to 0.5.
        n (int, optional): Número de intentos. Defaults to 5.

    Returns:
        int: Éxitos en la distribución binomial.
    """

    sum = 0

    for i in range(n):
        sum += Bernoulli(p)

    return sum

# ------------------------------------------------------------------------------

def Poisson(media, aleatorios:list):
    """Calcula la distribución de Poisson para la media especificada.

    Args:
        media (int): Media de la distribución de Poisson.
        aleatorios (list): Lista de valores para el cálculo.

    Returns:
        int: Valor de la distribución de Poisson.
    """

    y = 0
    x = 0
    bandera = True
    if aleatorios:
        q = iter(aleatorios)
    while bandera:
        if aleatorios:
            r = next(q)
        else:
            r = rnd.random()
        v = Exponencial(media, r)
        y = y + v
        if (y > 1):
            bandera = False
        else:
            x = x + 1
    return x

# ------------------------------------------------------------------------------

def BMCosenoNormal(mu, sigma, U = 0, V =0):
    """Genera un valor normal con media 'mu' y desviación 'sigma' usando el método de Box-Muller.

    Args:
        mu (float): Media de la distribución normal.
        sigma (float): Desviación estándar.
        U (float, optional): Valor aleatorio U. Generado al azar si no se proporciona.
        V (float, optional): Valor aleatorio V. Generado al azar si no se proporciona.

    Returns:
        float: Valor de la distribución normal.
    """
    if U == 0:
        U = rnd.random()
    if V == 0:
        V = rnd.random()
    normal = mt.sqrt((-2*mt.log(U)))*mt.cos(2*mt.pi*V)
    normal = mu+sigma*normal
    return normal

# ------------------------------------------------------------------------------

def BMSenoNormal(mu, sigma, U = 0, V =0):
    """Genera un valor normal con media 'mu' y desviación 'sigma' usando el método de Box-Muller.

    Args:
        mu (float): Media de la distribución normal.
        sigma (float): Desviación estándar.
        U (float, optional): Valor aleatorio U. Generado al azar si no se proporciona.
        V (float, optional): Valor aleatorio V. Generado al azar si no se proporciona.

    Returns:
        float: Valor de la distribución normal.
    """
    if U == 0:
        U = rnd.random()
    if V == 0:
        V = rnd.random()
    normal = mt.sqrt((-2*mt.log(U)))*mt.sin(2*mt.pi*V)
    normal = mu+sigma*normal
    return normal

