import numpy as np
from numpy import random as rnd
from math import log
import matplotlib.pyplot as plt
import statistics as st
from tqdm import tqdm

def LlegadaVehiculos():
    media = 300
    llegada_dia = np.random.poisson(media) # Total de vehículos para el día

    # Multiplica directamente las llegadas por las probabilidades
    automovil = int(llegada_dia * 0.45)
    moto = int(llegada_dia * 0.30)
    vehiculogrande = int(llegada_dia * 0.15)
    bus = int(llegada_dia * 0.05)
    otros = int(llegada_dia * 0.05)
    return llegada_dia, automovil, moto, vehiculogrande, bus, otros

def CapacidadTanque():
    #-------------------Automovil----------------
    Automovil = rnd.triangular(40,45,60)
    Inicial_Automovil = rnd.poisson(15)
    Capacidad_Automovil = Automovil - Inicial_Automovil
    #-------------------Moto-----------------------
    Moto = np.clip(rnd.normal(13,4), 10, 20)
    Inicial_Moto = rnd.triangular(1,5,19)
    Capacidad_Moto = Moto - Inicial_Moto
    #------------------Vehiculo_Grande-------------
    Vehiculo_grande = rnd.triangular(60,70,80)
    Inicial_Vgrande = rnd.triangular(10,15,50)
    Capacidad_Vgrande = Vehiculo_grande - Inicial_Vgrande
    #-----------------Bus------------------------
    Bus = np.clip(rnd.normal(200,50), 150, 250)
    # Usando la función Exponencial definida arriba
    Inicial_Bus = Exponencial(10) + Exponencial(10) + Exponencial(10)
    Capacidad_Bus = Bus - Inicial_Bus
    #------------------Otros-------------------
    Otros = rnd.uniform(300,400)
    Inicial_Otros = rnd.binomial(n= 100, p =0.5)
    Capacidad_Otros = Otros - Inicial_Otros
    return Capacidad_Automovil, Capacidad_Moto, Capacidad_Vgrande, Capacidad_Bus, Capacidad_Otros

def Recarga():
    litro = 1/3.785 #galones
    precio_litro = litro*16182
    Capacidad_Automovil, Capacidad_Moto, Capacidad_Vgrande, Capacidad_Bus, Capacidad_Otros = CapacidadTanque()
    llegada_dia, automovil, moto, vehiculogrande, bus, otros = LlegadaVehiculos()
    #----------Automovil----------------
    recarga_automovil = 0
    if automovil > 0:
        recarga_automovil_decision = Bernoulli(0.6)
        if recarga_automovil_decision == 1:
            recarga_automovil = int((Capacidad_Automovil * precio_litro) * automovil)
        else:
            recarga_automovil = (rnd.randint(20000, 50000)) * automovil

    #----------Moto---------------------
    recarga_moto = 0
    if moto > 0:
        recarga_moto_decision = Bernoulli(11/15)
        if recarga_moto_decision == 1:
            recarga_moto = int((Capacidad_Moto * precio_litro) * moto)
        else:
            recarga_moto = (rnd.randint(10000, 50000)) * moto

    #----------Vehiculos grandes--------------
    recarga_vgrandes = 0
    if vehiculogrande > 0:
        recarga_vgrandes_decision = Bernoulli(4/7)
        if recarga_vgrandes_decision == 1:
            recarga_vgrandes = int((Capacidad_Vgrande * precio_litro) * vehiculogrande)
        else:
            recarga_vgrandes = (rnd.randint(30000, 100000)) * vehiculogrande

    #---------------Bus------------------------
    recarga_bus = int((Capacidad_Bus * precio_litro) * bus)
    #----------------Otros--------------------
    recarga_otros = int((Capacidad_Otros * precio_litro) * otros)
    return recarga_automovil, recarga_moto, recarga_vgrandes, recarga_bus, recarga_otros

def SuperChorro():
    ventas_mensuales = 0
    #viene el modelo de simulacion
    for i in range(30): # para un mes
        #Aca se define cuanto se vende diariamente
        recarga_automovil, recarga_moto, recarga_vgrandes, recarga_bus, recarga_otros = Recarga()
        ventas_mensuales += recarga_automovil + recarga_moto + recarga_vgrandes + recarga_bus + recarga_otros
    return ventas_mensuales

