def AceptacionRechazo():
    # generamos 1000 puntos entre 20 y 100 para encontrar el máximo de f(x)
    xs   = np.linspace(20, 100, 1000)
    fmax = max([6*(x-20)*(100-x)/x**3 for x in xs])  # máximo real de la colina

    while True:
        x  = Uniforme(20, 100)           # generamos x aleatoria en el dominio
        u  = Uniforme(0, fmax)           # altura aleatoria hasta el tope real
        fx = 6*(x-20)*(100-x)/x**3      # altura de la colina en x

        if u <= fx:
            return x

def CantidadEmpanadas():
    dic_empanadas = {'Jueves': [], 'Viernes':[],'Sabado':[],'Domingo':[]}
    for dia in dic_empanadas.keys(): # Iterate over keys directly
        match dia:
            case 'Jueves':
                media = rnd.randint(450,700)
                desviacion = rnd.randint(100,200)
                cantidad = rnd.normal(media,desviacion)
                estalladas = rnd.binomial(4,0.05)
                disponibles_jueves = int(cantidad - estalladas)
                dic_empanadas['Jueves'].append(disponibles_jueves)
            case 'Viernes':
                media = rnd.randint(700,1000)
                desviacion = rnd.randint(400,500)
                cantidad = rnd.normal(media,desviacion)
                estalladas = rnd.triangular(17,33,65)
                disponibles_viernes = int(cantidad - estalladas)
                dic_empanadas['Viernes'].append(disponibles_viernes)
            case 'Sabado':
                media = rnd.randint(700,1000)
                desviacion = rnd.randint(400,500)
                cantidad = rnd.normal(media,desviacion)
                estalladas = AceptacionRechazo()
                disponibles_sabado = int(cantidad - estalladas)
                dic_empanadas['Sabado'].append(disponibles_sabado)
            case 'Domingo':
                media = rnd.randint(1500,2000)
                desviacion = rnd.randint(500,1000)
                cantidad = rnd.normal(media,desviacion)
                estalladas = AceptacionRechazo()
                disponibles_domingo = int(cantidad - estalladas)
                dic_empanadas['Domingo'].append(disponibles_domingo)
    return dic_empanadas

def llegadaClientes():
    c_jueves = rnd.poisson(50)
    c_viernes = rnd.poisson(85)
    c_sabado = rnd.poisson(100)
    c_domingo = rnd.poisson(180)
    return c_jueves,c_viernes,c_sabado,c_domingo

def Compra(): # me dice cuantas empanadas quiere comprar cada cliente
    c_jueves,c_viernes,c_sabado,c_domingo = llegadaClientes()
    dic_clientes = {'Jueves': c_jueves, 'Viernes': c_viernes, 'Sabado': c_sabado, 'Domingo':c_domingo}
    dic_compra = {'Jueves': [], 'Viernes':[],'Sabado':[],'Domingo':[]}
    #Cantidad de empanadas que compra cada cliente
    for dia in dic_clientes.keys():
        for i in range(dic_clientes[dia]):
            empanadas = rnd.geometric(0.1)
            dic_compra[dia].append(empanadas)
    return dic_compra



def Venta():
    empanadas = {
    'papa_guiso':       {'prob': 0.50, 'valor': 1000, 'ganancia': 0.30},
    'papa_carne':       {'prob': 0.15, 'valor': 1500, 'ganancia': 0.20},
    'arroz_papa_carne': {'prob': 0.05, 'valor': 1600, 'ganancia': 0.25},
    'carne':            {'prob': 0.10, 'valor': 2000, 'ganancia': 0.05},
    'jamon_queso':      {'prob': 0.20, 'valor': 2000, 'ganancia': 0.10},
    }
    dic_empanadas = CantidadEmpanadas()
    dic_compra = Compra()
    dic_venta = {'Jueves': [], 'Viernes':[],'Sabado':[],'Domingo':[]}
    dic_ganancias = {'Jueves': [], 'Viernes':[],'Sabado':[],'Domingo':[]}

    for dia in dic_compra.keys():
        empanadas_disponibles = dic_empanadas[dia][0]
        for c in dic_compra[dia]:
            for i in range(c):
                if empanadas_disponibles > 0:
                    x = rnd.random()
                    if x < empanadas['papa_guiso']['prob']:
                        dic_venta[dia].append(empanadas['papa_guiso']['valor'])
                        dic_ganancias[dia].append(empanadas['papa_guiso']['valor'] * empanadas['papa_guiso']['ganancia'])

                    elif x < empanadas['papa_guiso']['prob'] + empanadas['papa_carne']['prob']:
                        dic_venta[dia].append(empanadas['papa_carne']['valor'])
                        dic_ganancias[dia].append(empanadas['papa_carne']['valor'] * empanadas['papa_carne']['ganancia'])

                    elif x < empanadas['papa_guiso']['prob'] + empanadas['papa_carne']['prob'] + empanadas['arroz_papa_carne']['prob']:
                        dic_venta[dia].append(empanadas['arroz_papa_carne']['valor'])
                        dic_ganancias[dia].append(empanadas['arroz_papa_carne']['valor'] * empanadas['arroz_papa_carne']['ganancia'])

                    elif x < empanadas['papa_guiso']['prob'] + empanadas['papa_carne']['prob'] + empanadas['arroz_papa_carne']['prob'] + empanadas['carne']['prob']:
                        dic_venta[dia].append(empanadas['carne']['valor'])
                        dic_ganancias[dia].append(empanadas['carne']['valor'] * empanadas['carne']['ganancia'])

                    else:
                        dic_venta[dia].append(empanadas['jamon_queso']['valor'])
                        dic_ganancias[dia].append(empanadas['jamon_queso']['valor'] * empanadas['jamon_queso']['ganancia'])

                    empanadas_disponibles -= 1  # descontar del inventario
    dic_ganancias_dia = {dia: sum(dic_ganancias[dia]) for dia in dic_ganancias.keys()}
    dic_ventas_dia = {dia:sum(dic_venta[dia]) for dia in dic_venta.keys()}
    return dic_ganancias_dia, dic_ventas_dia

def EmpanadasJesus():
    #viene el modelo de simulacion para 6 meses, 24 semanas
    dic_ganancias_dia, dic_ventas_dia = Venta()
    ganancias_total = 0
    ventas_total = 0
    for i in range(24):
        #definimos que pasa en cada semana
        ventas_semana = sum(list(dic_ventas_dia.values()))
        ventas_total += ventas_semana
        ganancias_semana = sum(list(dic_ganancias_dia.values()))
        ganancias_total += ganancias_semana
        #definimos que pasa cada dia
        for i in range(4):
            if i == 0:
                dia = 'Jueves'
                venta_jueves = dic_ventas_dia['Jueves']
                ganancia_jueves = dic_ganancias_dia['Jueves']
            if i == 1:
                dia = 'Viernes'
                venta_viernes = dic_ventas_dia['Viernes']
                ganancia_viernes = dic_ganancias_dia['Viernes']
            if i == 2:
                dia = 'Sabado'
                venta_sabado = dic_ventas_dia['Sabado']
                ganancia_sabado = dic_ganancias_dia['Sabado']
            if i == 3:
                dia = 'Domingo'
                venta_domingo = dic_ventas_dia['Domingo']
                ganancia_domingo = dic_ganancias_dia['Domingo']
    return ganancias_total, ventas_total, venta_jueves, venta_viernes, venta_sabado, venta_domingo, ganancia_jueves, ganancia_viernes, ganancia_sabado, ganancia_domingo

ganancias_total, ventas_total, venta_jueves, venta_viernes, venta_sabado, venta_domingo, ganancia_jueves, ganancia_viernes, ganancia_sabado, ganancia_domingo = EmpanadasJesus()
print(f'Ganancias totales: {ganancias_total}')
print(f'Ventas totales: {ventas_total}')

num_simulaciones = 1000

