for _ in tqdm(range(num_simulaciones), desc="Simulando Empanadas Jesus"): # Modificado para tqdm
    gan_total, ven_total, ven_j, ven_v, ven_s, ven_d, gan_j, gan_v, gan_s, gan_d = EmpanadasJesus()
    vGananciasTotal.append(gan_total)
